/// Generate release notes for a git tag
#[derive(Args)]
#[usage(effect = "read")]
pub struct GenerateArgs {
    /// Push editorialized notes to the GitHub release
    #[usage(long = "github-release", effect = "write")]
    pub github_release: bool,
    /// Update CHANGELOG.md with the generated changelog entry
    #[usage(long = "changelog", effect = "write")]
    pub changelog: bool,
    /// Output concise changelog entry instead of detailed notes
    #[usage(long = "concise")]
    pub concise: bool,
    /// Generate notes without updating GitHub or verifying links
    #[usage(long = "dry-run", short = 'n')]
    pub dry_run: bool,
    /// GitHub repo in owner/repo format (auto-detected from git remote)
    #[usage(long = "repo", value_name = "REPO")]
    pub repo: ::std::option::Option<::std::string::String>,
    /// LLM model to use
    #[usage(long = "model", value_name = "MODEL")]
    pub model: ::std::option::Option<::std::string::String>,
    /// Max response tokens
    #[usage(long = "max-tokens", value_name = "MAX_TOKENS")]
    pub max_tokens: ::std::option::Option<::std::string::String>,
    /// LLM provider (anthropic or openai, auto-detected from model if omitted)
    #[usage(long = "provider", value_name = "PROVIDER")]
    pub provider: ::std::option::Option<::std::string::String>,
    /// Base URL for the LLM API
    #[usage(long = "base-url", value_name = "BASE_URL")]
    pub base_url: ::std::option::Option<::std::string::String>,
    /// Write output to a file instead of stdout
    #[usage(long = "output", short = 'o', effect = "write", value_name = "OUTPUT")]
    pub output: ::std::option::Option<::std::string::String>,
    /// Git tag to generate release notes for
    #[usage(arg, name = "TAG")]
    pub tag: ::std::string::String,
    /// Previous tag (auto-detected if omitted)
    #[usage(arg, name = "PREV_TAG")]
    pub prev_tag: ::std::option::Option<::std::string::String>,
}

